css:
:scope{display:block;width:100%}
.pw{--ink:#010A12;--bone:#EDE6D8;--stone:#E0D9CB;--sand:#BBAFA3;--oxblood:#321013;--mulberry:#5E3A3C;--clay:#8C5B46;--gilt:#C6A15B;--head:'Cormorant Garamond',serif;--body:'EB Garamond',serif;--label:'Montserrat',sans-serif;position:relative;font-family:var(--body);font-size:21px;line-height:1.5;font-weight:400;letter-spacing:0;-webkit-font-smoothing:antialiased;text-align:left}
.pw *{box-sizing:border-box}
:where(.pw p,.pw h1,.pw h2,.pw h3,.pw ul,.pw ol,.pw li){margin:0;padding:0}
:where(.pw p,.pw li,.pw h1,.pw h2,.pw h3){text-wrap:wrap}
:where(.pw h1,.pw h2,.pw h3){color:inherit}
:where(.pw){overflow-wrap:normal}
.in{max-width:1200px;margin:0 auto;padding:0 32px}
.narrow{max-width:1000px}
.pad{padding:160px 0}
.kick{margin:0;font-family:var(--label);font-weight:400;font-size:12px;line-height:18px;letter-spacing:.32em;text-transform:uppercase}
.rule{width:64px;height:1px;background:var(--clay);border:0;margin:28px 0 32px}
.pw h2{font-family:var(--head);font-weight:500;font-size:60px;line-height:1.08;letter-spacing:0;text-wrap:balance}
.g-ink{background:var(--ink);color:var(--bone)}.g-ink .kick{color:var(--sand)}
.g-bone{background:var(--bone);color:var(--ink)}.g-bone .kick{color:var(--mulberry)}
.g-stone{background:var(--stone);color:var(--ink)}.g-stone .kick{color:var(--mulberry)}.g-stone .rule{background:var(--ink)}
.g-oxblood{background:var(--oxblood);color:var(--bone)}.g-oxblood .kick{color:var(--sand)}.g-oxblood .rule{background:var(--sand)}
.g-clay{background:var(--clay);color:var(--bone)}.g-clay .kick{color:var(--bone)}.g-clay .rule{background:var(--bone)}
.cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:64px 80px}
.blk h2{font-size:44px;line-height:1.1}
.b{margin:20px 0 0;max-width:30em}
.btn{display:inline-flex;align-items:center;justify-content:center;min-height:52px;margin-top:36px;padding:0 32px;font-family:var(--label);font-weight:400;font-size:12px;line-height:1.5;letter-spacing:.26em;text-transform:uppercase;text-decoration:none;border:1px solid currentColor;color:inherit;background:transparent;transition:background .45s ease,color .45s ease,border-color .45s ease}
.g-bone .btn,.g-stone .btn{border-color:var(--ink)}
.g-bone .btn:hover,.g-stone .btn:hover,.g-bone .btn:focus-visible,.g-stone .btn:focus-visible{background:var(--ink);color:var(--bone)}
.g-ink .btn,.g-oxblood .btn{border-color:var(--clay);color:var(--bone)}
.g-ink .btn:hover,.g-oxblood .btn:hover,.g-ink .btn:focus-visible,.g-oxblood .btn:focus-visible{background:var(--clay)}
.g-clay .btn{border-color:var(--bone);color:var(--bone)}
.g-clay .btn:hover,.g-clay .btn:focus-visible{background:var(--ink);border-color:var(--ink)}
.btn:focus-visible{outline:2px solid var(--clay);outline-offset:3px}
@media (max-width:767px){.pw{font-size:19px}.in{padding:0 20px}.pad{padding:88px 0}.pw h2{font-size:40px}.blk h2{font-size:34px}}
@media (prefers-reduced-motion:reduce){.btn{transition:none}}
.js-rv .rv{opacity:0;transform:translateY(16px);transition:opacity 1.3s ease,transform 1.3s ease}
.js-rv .rv.on{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){.js-rv .rv{opacity:1;transform:none;transition:none}}
